export function createEventEmitter() {
  const events = new Map<string, Array<{ fn: Function; once: boolean }>>>();

  function on(event: string, listener: Function): number {
    const current = events.get(event) || [];
    current.push({ fn: listener, once: false });
    events.set(event, current);
    return current.length;
  }

  function once(event: string, listener: Function): number {
    const current = events.get(event) || [];
    current.push({ fn: listener, once: true });
    events.set(event, current);
    return current.length;
  }

  function off(event: string, listener: Function): boolean {
    const current = events.get(event) || [];
    for (let i = 0; i < current.length; i++) {
      if (current[i].fn === listener) {
        current.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload?: any): any[] {
    const current = events.get(event) || [];
    const results: any[] = [];
    const removeIndices = new Set<number>();

    for (let i = 0; i < current.length; i++) {
      const listenerObj = current[i];
      results.push(listenerObj.fn(payload));
      if (listenerObj.once) {
        removeIndices.add(i);
      }
    }

    for (let i = current.length - 1; i >= 0; i--) {
      if (removeIndices.has(i)) {
        current.splice(i, 1);
      }
    }

    return results;
  }

  function listenerCount(event: string): number {
    const current = events.get(event) || [];
    return current.length;
  }

  return { on, once, off, emit, listenerCount };
}

type Listener = (payload: unknown) => unknown;
type ListenerEntry = {
  fn: Listener;
  isOnce: boolean;
};

class EventEmitter {
  private events: Record<string, ListenerEntry[]> = {};

  on(event: string, listener: Listener): number {
    this.events[event] = this.events[event] || [];
    this.events[event].push({ fn: listener, isOnce: false });
    return this.events[event].length;
  }

  once(event: string, listener: Listener): number {
    this.events[event] = this.events[event] || [];
    this.events[event].push({ fn: listener, isOnce: true });
    return this.events[event].length;
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this.events[event] || [];
    const index = listeners.findIndex(entry => entry.fn === listener);
    if (index !== -1) {
      this.events[event]?.splice(index, 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.events[event] || [];
    const results: unknown[] = [];
    const onceEntries: ListenerEntry[] = [];

    for (const entry of listeners) {
      results.push(entry.fn(payload));
      if (entry.isOnce) {
        onceEntries.push(entry);
      }
    }

    if (onceEntries.length > 0) {
      this.events[event] = listeners.filter(entry => !entry.isOnce);
    }

    return results;
  }

  listenerCount(event: string): number {
    return (this.events[event] || []).length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter();
}

export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const storage = new Map<string, number[]>();
  return {
    allow(key, nowMs) {
      let timestamps = storage.get(key);
      if (!timestamps) {
        timestamps = [];
        storage.set(key, timestamps);
      }
      const cutoff = nowMs - 1000;
      const filteredCount = timestamps.filter(ts => ts > cutoff).length;
      if (filteredCount < 3) {
        timestamps.push(nowMs);
        return true;
      }
      return false;
    },
    remaining(key, nowMs) {
      const timestamps = storage.get(key) || [];
      const cutoff = nowMs - 1000;
      const currentCount = timestamps.filter(ts => ts > cutoff).length;
      return Math.max(3 - currentCount, 0);
    },
    reset(key) {
      storage.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const storage = new Map<string, { count: number; windowStart: number }>();

  function allow(key: string, nowMs: number): boolean {
    let entry = storage.get(key);
    if (!entry) {
      entry = { count: 0, windowStart: nowMs };
      storage.set(key, entry);
    } else {
      const elapsed = nowMs - entry.windowStart;
      if (elapsed >= windowMs) {
        entry.count = 0;
        entry.windowStart = nowMs;
      }
    }
    if (entry.count < limit) {
      entry.count++;
      return true;
    } else {
      return false;
    }
  }

  function remaining(key: string, nowMs: number): number {
    let entry = storage.get(key);
    if (!entry) {
      return limit;
    }
    const elapsed = nowMs - entry.windowStart;
    if (elapsed >= windowMs) {
      entry.count = 0;
      entry.windowStart = nowMs;
    }
    return Math.max(limit - entry.count, 0);
  }

  function reset(key: string): void {
    storage.delete(key);
  }

  return { allow, remaining, reset };
}

