export function createTodoApp() {
  let todos: { id: number; text: string; completed: boolean }[] = [];
  let nextId = 1;

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const newTodo: { id: number; text: string; completed: boolean } = {
      id: nextId,
      text,
      completed: false,
    };
    todos.push(newTodo);
    nextId += 1;
    return newTodo;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => {
    return todos.find(t => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const index = todos.findIndex(t => t.id === id);
    if (index >= 0) {
      todos[index].completed = !todos[index].completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const index = todos.findIndex(t => t.id === id);
    if (index >= 0) {
      todos.splice(index, 1);
      return true;
    }
    return false;
  };

  const listTodos = (): { id: number; text: string; completed: boolean }[] => {
    return [...todos];
  };

  const listCompleted = (): { id: number; text: string; completed: boolean }[] => {
    return todos.filter(t => t.completed);
  };

  const listPending = (): { id: number; text: string; completed: boolean }[] => {
    return todos.filter(t => !t.completed);
  };

  const clearCompleted = (): void => {
    todos = todos.filter(t => !t.completed);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

