export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();
  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs;
      cache.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      return entry ? (nowMs < entry.expiresAt ? entry.value : undefined) : undefined;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const [key, val] of cache.entries()) {
        if (nowMs < val.expiresAt) count++;
      }
      return count;
    },
    clear() {
      cache.clear();
    }
  };
}

export function createTtlCache() {
  const cacheMap = new Map<string, { value: unknown; expires: number }>();

  function cleanupExpired(nowMs: number) {
    const keys: string[] = [];
    for (const [key, { expires }] of cacheMap) {
      if (nowMs >= expires) {
        keys.push(key);
      }
    }
    for (const key of keys) {
      cacheMap.delete(key);
    }
  }

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs?: number
  ) {
    const expires = nowMs + (ttlMs ?? 1000);
    cacheMap.set(key, { value, expires });
  }

  function get(key: string, nowMs: number): unknown {
    cleanupExpired(nowMs);
    const entry = cacheMap.get(key);
    return entry?.value ?? undefined;
  }

  function has(key: string, nowMs: number): boolean {
    cleanupExpired(nowMs);
    return cacheMap.has(key);
  }

  function _delete(key: string): boolean {
    const nowMs = Date.now();
    cleanupExpired(nowMs);
    if (cacheMap.has(key)) {
      cacheMap.delete(key);
      return true;
    }
    return false;
  }

  function size(nowMs: number): number {
    cleanupExpired(nowMs);
    return cacheMap.size;
  }

  function clear(): void {
    cacheMap.clear();
  }

  return {
    set,
    get,
    has,
    delete: _delete,
    size,
    clear,
  };
}

