export function createRateLimiter() {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, {count: number, windowStart: number}>();

  function allow(key: string, nowMs: number): boolean {
    let entry = store.get(key);
    let count: number, windowStart: number;
    if (!entry) {
      count = 0;
      windowStart = nowMs;
    } else {
      ({count, windowStart} = entry);
      if (nowMs - windowStart >= windowMs) {
        count = 0;
        windowStart = nowMs;
      }
    }
    if (count < limit) {
      count++;
      store.set(key, {count, windowStart});
      return true;
    } else {
      // ensure stored count is limit
      store.set(key, {count, windowStart});
      return false;
    }
  }

  function remaining(key: string, nowMs: number): number {
    let entry = store.get(key);
    if (!entry) return limit;
    let {count, windowStart} = entry;
    if (nowMs - windowStart >= windowMs) {
      return limit;
    }
    return Math.max(limit - count, 0);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return {allow, remaining, reset};
}

