interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

class Calculator implements Calculator {
  private currentValue: number = 0;
  private memory: number = 0;

  add(n: number): Calculator {
    this.currentValue += n;
    return this;
  }

  subtract(n: number): Calculator {
    this.currentValue -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this.currentValue *= n;
    return this;
  }

  divide(n: number): Calculator {
    this.currentValue /= n;
    return this;
  }

  clear(): Calculator {
    this.currentValue = 0;
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): Calculator {
    this.memory = this.currentValue;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }

  memoryAdd(): Calculator {
    this.memory += this.currentValue;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new Calculator();
}

export function createEventEmitter<T = unknown>() {
  type Listener = (...args: T[]) => unknown;
  const events: Record<string, Array<{ fn: Listener; once: boolean }>> = {};

  const on = (event: string, listener: Listener): number => {
    if (!events[event]) {
      events[event] = [];
    }
    events[event].push({ fn: listener, once: false });
    return events[event].length;
  };

  const once = (event: string, listener: Listener): number => {
    if (!events[event]) {
      events[event] = [];
    }
    events[event].push({ fn: listener, once: true });
    return events[event].length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const listeners = events[event];
    if (!listeners) {
      return false;
    }
    const index = listeners.findIndex(({ fn }) => fn === listener);
    if (index !== -1) {
      listeners.splice(index, 1);
      return true;
    }
    return false;
  };

  const emit = (event: string, payload: T): unknown[] => {
    const listeners = events[event];
    if (!listeners) {
      return [];
    }

    const results: unknown[] = [];
    // Iterate backwards to safely splice 'once' listeners
    for (let i = listeners.length - 1; i >= 0; i--) {
      const { fn, once } = listeners[i];
      const result = fn(payload);
      results.push(result);

      if (once) {
        listeners.splice(i, 1);
      }
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    return events[event]?.length ?? 0;
  };

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

