  const events = new Map<string, Array<{ fn: Listener; isOnce: boolean }>>()

  const getListeners = (event: string): Array<{ fn: Listener; isOnce: boolean }> => {
    if (!events.has(event)) {
      events.set(event, [])
    }
    return events.get(event)!
  }

  const ee: EventEmitter = {
    on(event: string, listener: Listener): number {
      getListeners(event).push({ fn: listener, isOnce: false })
      return getListeners(event).length
    },
    once(event: string, listener: Listener): number {
      getListeners(event).push({ fn: listener, isOnce: true })
      return getListeners(event).length
    },
    off(event: string, listener: Listener): boolean {
      const listeners = getListeners(event)
      const index = listeners.findIndex(l => l.fn === listener)
      if (index !== -1) {
        listeners.splice(index, 1)
        return true
      }
      return false
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = getListeners(event)
      const results: unknown[] = []
      for (let i = listeners.length - 1; i >= 0; i--) {
        const wrapper = listeners[i]
        if (wrapper.isOnce) {
          listeners.splice(i, 1)
        }
        results.push(wrapper.fn(payload))
      }
      return results
    },
    listenerCount(event: string): number {
      return getListeners(event).length
    },
  }

  return ee
}

export function createRateLimiter() {
    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;
    const state = new Map<string, { count: number; start: number }>();

    function allow(key: string, nowMs: number): boolean {
        const current = state.get(key);
        if (!current) {
            state.set(key, { count: 1, start: nowMs });
            return true;
        }
        if (nowMs - current.start >= WINDOW_MS) {
            state.set(key, { count: 1, start: nowMs });
            return true;
        }
        if (current.count < MAX_REQUESTS) {
            current.count++;
            return true;
        }
        return false;
    }

    function remaining(key: string, nowMs: number): number {
        const current = state.get(key);
        if (!current) {
            return MAX_REQUESTS;
        }
        if (nowMs - current.start >= WINDOW_MS) {
            return MAX_REQUESTS;
        }
        return Math.max(0, MAX_REQUESTS - current.count);
    }

    function reset(key: string): void {
        state.delete(key);
    }

    return { allow, remaining, reset };
}

const LIMIT = 3;
const WINDOW_MS = 1000;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

function createRateLimiter(): RateLimiter {
  const store = new Map<string, { count: number; lastResetTime: number }>();

  const getOrCreateState = (key: string, nowMs: number): { count: number; lastResetTime: number } => {
    let state = store.get(key);
    if (!state) {
      state = { count: 0, lastResetTime: nowMs };
      store.set(key, state);
    }
    return state;
  };

  const updateWindow = (state: { count: number; lastResetTime: number }, nowMs: number): void => {
    if (nowMs - state.lastResetTime >= WINDOW_MS) {
      state.count = 0;
      state.lastResetTime = nowMs;
    }
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateState(key, nowMs);
      updateWindow(state, nowMs);
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = getOrCreateState(key, nowMs);
      updateWindow(state, nowMs);
      return Math.max(0, LIMIT - state.count);
    },

    reset(key: string): void {
      store.delete(key);
    }
  };
}

