export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Array<{listener: Listener, once: boolean}>> = {};

  return {
    on(event, listener) {
      if (!listeners[event]) listeners[event] = [];
      listeners[event].push({listener, once: false});
      return listeners[event]!.length;
    },
    once(event, listener) {
      if (!listeners[event]) listeners[event] = [];
      listeners[event].push({listener, once: true});
      return listeners[event]!.length;
    },
    off(event, listener) {
      const arr = listeners[event];
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].listener === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const arr = listeners[event];
      if (!arr) return [];
      const results: unknown[] = [];
      for (let i = 0; i < arr.length; i++) {
        const entry = arr[i];
        const ret = entry.listener(payload);
        results.push(ret);
        if (entry.once) {
          arr.splice(i, 1);
          i--;
        }
      }
      return results;
    },
    listenerCount(event) {
      return (listeners[event] ?? []).length;
    }
  };
