export function createRateLimiter() {
  const queues = new Map<string, number[]>();

  function allow(key: string, nowMs: number): boolean {
    const arr = queues.get(key) ?? [];
    const recent = arr.filter(ts => ts > nowMs - 1000);
    if (recent.length >= 3) return false;
    recent.push(nowMs);
    queues.set(key, recent);
    return true;
  }

  function remaining(key: string, nowMs: number): number {
    const arr = queues.get(key) ?? [];
    const recent = arr.filter(ts => ts > nowMs - 1000);
    return Math.max(0, 3 - recent.length);
  }

  function reset(key: string): void {
    queues.delete(key);
  }

  return { allow, remaining, reset };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, {count: number; windowStart: number}>();

  const getBucketStart = (nowMs: number): number => Math.floor(nowMs / windowMs) * windowMs;

  return {
    allow(key: string, nowMs: number): boolean {
      const bucketStart = getBucketStart(nowMs);
      let entry = store.get(key) ?? {count: 0, windowStart: bucketStart};

      if (entry.windowStart !== bucketStart) {
        entry = {count: 0, windowStart: bucketStart};
      }

      if (entry.count < limit) {
        entry.count++;
        store.set(key, entry);
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const bucketStart = getBucketStart(nowMs);
      let entry = store.get(key) ?? {count: 0, windowStart: bucketStart};

      if (entry.windowStart !== bucketStart) {
        entry = {count: 0, windowStart: bucketStart};
      }

      return Math.max(0, limit - entry.count);
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}

