export function createTtlCache(): TtlCache {
  const defaultTTL = 1000
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  const isExpired = (now: number, expiresAt: number): boolean => now >= expiresAt

  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = ttlMs !== undefined ? nowMs + ttlMs : nowMs + defaultTTL
      store.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      const entry = store.get(key)
      return entry && !isExpired(nowMs, entry.expiresAt) ? entry.value : undefined
    },
    has(key, nowMs) {
      const entry = store.get(key)
      return entry && !isExpired(nowMs, entry.expiresAt)
    },
    delete(key) {
      return store.delete(key)
    },
    size(nowMs) {
      let count = 0
      for (const { expiresAt } of store.values()) {
        if (!isExpired(nowMs, expiresAt)) count++
      }
      return count
    },
    clear() {
      store.clear()
    },
  }
}

