export function createEventEmitter() {
  const events = new Map<Symbol, { listeners: CallableFunction[]; onceListeners: CallableFunction[] }>();

  return {
    on(event: Symbol, listener: CallableFunction): number {
      if (!events.has(event)) {
        events.set(event, { listeners: [], onceListeners: [] });
      }
      const eventObj = events.get(event)!;
      eventObj.listeners.push(listener);
      return eventObj.listeners.length + eventObj.onceListeners.length;
    },

    once(event: Symbol, listener: CallableFunction): number {
      if (!events.has(event)) {
        events.set(event, { listeners: [], onceListeners: [] });
      }
      const eventObj = events.get(event)!;
      eventObj.onceListeners.push(listener);
      return eventObj.listeners.length + eventObj.onceListeners.length;
    },

    off(event: Symbol, listener: CallableFunction): boolean {
      if (!events.has(event)) return false;
      const eventObj = events.get(event)!;

      const index = eventObj.listeners.indexOf(listener);
      if (index !== -1) {
        eventObj.listeners.splice(index, 1);
        return true;
      }

      const onceIndex = eventObj.onceListeners.indexOf(listener);
      if (onceIndex !== -1) {
        eventObj.onceListeners.splice(onceIndex, 1);
        return true;
      }

      return false;
    },

    emit(event: Symbol, payload: unknown): unknown[] {
      const results: unknown[] = [];
      if (!events.has(event)) return results;

      const eventObj = events.get(event)!;

      for (const listener of eventObj.listeners) {
        results.push(listener(payload));
      }

      for (const listener of eventObj.onceListeners) {
        results.push(listener(payload));
        eventObj.onceListeners.shift();
      }

      return results;
    },

    listenerCount(event: Symbol): number {
      return events.get(event)?.listeners.length ?? 0 + events.get(event)?.onceListeners.length ?? 0;
    },
  };
}

export type EventEmitter = ReturnType<typeof createEventEmitter>;
