type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

class EventEmitterImpl {
  private listeners: Map<string, Listener[]> = new Map()

  on(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }
    const eventListeners = this.listeners.get(event)!
    eventListeners.push(listener)
    return eventListeners.length
  }

  once(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }
    const eventListeners = this.listeners.get(event)!
    const onceWrapper = (payload: unknown) => {
      const result = listener(payload)
      if ((onceWrapper as any).triggerOnce) {
        (onceWrapper as any).triggerOnce = false
        const index = eventListeners.indexOf(onceWrapper)
        if (index !== -1) {
          eventListeners.splice(index, 1)
        }
      }
      return result
    }
    ;(onceWrapper as any).triggerOnce = true
    eventListeners.push(onceWrapper)
    return eventListeners.length
  }

  off(event: string, listener: Listener): boolean {
    const eventListeners = this.listeners.get(event)
    if (!eventListeners) {
      return false
    }
    const index = eventListeners.indexOf(listener)
    if (index === -1) {
      return false
    }
    eventListeners.splice(index, 1)
    return true
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventListeners = this.listeners.get(event) || []
    const results: unknown[] = []
    const remainingListeners = eventListeners.filter((listener) => {
      if ((listener as any).triggerOnce) {
        results.push(listener(payload))
        return false
      }
      results.push(listener(payload))
      return true
    })
    this.listeners.set(event, remainingListeners)
    return results
  }

  listenerCount(event: string): number {
    return this.listeners.get(event)?.length || 0
  }
}

function createEventEmitter(): EventEmitter {
  return new EventEmitterImpl()
}

export { createEventEmitter, EventEmitter, Listener }
