export function createRateLimiter() {
  interface KeyState {
    requests: number;
    windowStart: number;
  }

  const keys = new Map<string, KeyState>();

  const ALLOWED_REQUESTS = 3;
  const WINDOW_MS = 1000;

  function getOrCreateKeyState(key: string, nowMs: number): KeyState {
    if (!keys.has(key)) {
      keys.set(key, {
        requests: 0,
        windowStart: nowMs
      });
      return keys.get(key)!;
    }

    const state = keys.get(key)!;

    if (nowMs - state.windowStart >= WINDOW_MS) {
      state.requests = 0;
      state.windowStart = nowMs;
    }

    return state;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateKeyState(key, nowMs);

      if (state.requests < ALLOWED_REQUESTS) {
        state.requests += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = getOrCreateKeyState(key, nowMs);

      const timeInWindow = nowMs - state.windowStart;
      const requestsInWindow = state.requests;
      const availableTime = WINDOW_MS - timeInWindow;
      const timePerRequest = WINDOW_MS / ALLOWED_REQUESTS;

      if (requestsInWindow < ALLOWED_REQUESTS) {
        const remainingAfterCurrent = Math.ceil(
          (availableTime - timePerRequest / 1000 * requestsInWindow) / timePerRequest
        );
        return Math.max(0, remainingAfterCurrent);
      }
      return 0;
    },

    reset(key: string): void {
      keys.delete(key);
    }
  };
}
