type RecordValue = {
  count: number
  windowStart: number
}

const limit = 3
const windowMs = 1000

export function createRateLimiter(): RateLimiter {
  const keyState = new Map<string, RecordValue>()

  return {
    allow(key: string, nowMs: number): boolean {
      let record = keyState.get(key)

      if (!record || nowMs - record.windowStart >= windowMs) {
        record = {
          count: 0,
          windowStart: nowMs
        }
        keyState.set(key, record)
      }

      if (record.count < limit) {
        record.count++
        keyState.set(key, record)
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      let record = keyState.get(key)

      if (!record || nowMs - record.windowStart >= windowMs) {
        record = {
          count: 0,
          windowStart: nowMs
        }
        keyState.set(key, record)
      }

      return Math.max(0, limit - record.count)
    },

    reset(key: string): void {
      keyState.delete(key)
    }
  }
}
