export function createTtlCache() {
  type Entry = {
    value: unknown
    expiresAt: number
  };

  const entries = new Map<string, Entry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = ttlMs === undefined ? nowMs + 1000 : nowMs + ttlMs;
      entries.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return entries.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      entries.clear();
    },
  };
}
