export function createTtlCache(): TtlCache {
  interface CacheEntry {
    value: unknown;
    expiresAt: number;
  }

  const entries = new Map<string, CacheEntry>();

  const set = (key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void => {
    entries.set(key, {
      value,
      expiresAt: ttlMs === 0 ? nowMs : nowMs + ttlMs
    });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = entries.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      entries.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = entries.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      entries.delete(key);
      return false;
    }
    return true;
  };

  const deleteEntry = (key: string): boolean => entries.delete(key);

  const sizeCache = (nowMs: number): number => entries.size;

  const clearCache = (): void => entries.clear();

  return {
    set,
    get,
    has,
    delete: deleteEntry,
    size: sizeCache,
    clear: clearCache
  };
}
