export function createEventEmitter() {
  const listeners: Record<string, Array<{ fn: (...args: any) => any; oneTime: boolean }>> = {};

  function listenerCount(event: string): number {
    return (listeners[event]?.length ?? 0);
  }

  function on(event: string, listener: (...args: any) => any): number {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push({ fn: listener, oneTime: false });
    return listenerCount(event);
  }

  function once(event: string, listener: (...args: any) => any): number {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push({ fn: listener, oneTime: true });
    return listenerCount(event);
  }

  function off(event: string, listener: (...args: any) => any): boolean {
    const arr = listeners[event];
    if (!arr) return false;
    const idx = arr.findIndex(l => l.fn === listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    return true;
  }

  function emit(event: string, payload: any): any[] {
    const arr = listeners[event];
    if (!arr) return [];
    const results: any[] = [];
    const slice = [...arr];
    for (const entry of slice) {
      const ret = entry.fn(payload);
      results.push(ret);
      if (entry.oneTime) {
        const removeIdx = arr.findIndex(e => e.fn === entry.fn && e.oneTime === entry.oneTime);
        if (removeIdx !== -1) arr.splice(removeIdx, 1);
      }
    }
    return results;
  }

  return { on, once, off, emit, listenerCount };
}

export function createEventEmitter(): any {
  type Listener = (payload: unknown) => unknown;

  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>();

  function on(event: string, listener: Listener): number {
    const arr = listeners.get(event) ?? [];
    arr.push({ listener, once: false });
    listeners.set(event, arr);
    return arr.length;
  }

  function once(event: string, listener: Listener): number {
    const arr = listeners.get(event) ?? [];
    arr.push({ listener, once: true });
    listeners.set(event, arr);
    return arr.length;
  }

  function off(event: string, listener: Listener): boolean {
    const arr = listeners.get(event);
    if (!arr) return false;
    const idx = arr.findIndex(r => r.listener === listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    return true;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results = arr.map(r => r.listener(payload));
    for (let i = arr.length - 1; i >= 0; i--) {
      if (arr[i].once) {
        arr.splice(i, 1);
      }
    }
    return results;
  }

  function listenerCount(event: string): number {
    return listeners.get(event)?.length ?? 0;
  }

  return { on, once, off, emit, listenerCount };
}

export function createRateLimiter() {
  const store = new Map<string, number[]>();
  function cleanup(arr: number[], nowMs: number): number[] {
    while (arr.length && nowMs - arr[0] >= 1000) arr.shift();
    return arr;
  }
  const allow = (key: string, nowMs: number): boolean => {
    let timestamps = store.get(key);
    if (!timestamps) {
      timestamps = [];
      store.set(key, timestamps);
    }
    timestamps = cleanup(timestamps, nowMs);
    timestamps.push(nowMs);
    return timestamps.length <= 3;
  };
  const remaining = (key: string, nowMs: number): number => {
    let timestamps = store.get(key) || [];
    while (timestamps.length && nowMs - timestamps[0] >= 1000) timestamps.shift();
    return Math.max(3 - timestamps.length, 0);
  };
  const reset = (key: string) => {
    store.delete(key);
  };
  return { allow, remaining, reset };
}

