export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, {count: number; windowStart: number}>();

  function getWindowStart(key: string, nowMs: number): number {
    const entry = store.get(key);
    if (!entry) return nowMs;
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    return entry.windowStart;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = store.get(key);
      if (!entry) {
        entry = {count: 0, windowStart: nowMs};
        store.set(key, entry);
      }
      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }
      if (entry.count < limit) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = store.get(key);
      if (!entry) return limit;
      if (nowMs - entry.windowStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }
      const remaining = limit - entry.count;
      return remaining > 0 ? remaining : 0;
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}
