export function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      store.set(key, { value, expiresAt });
    },

    get(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = store.get(key);
      return entry && nowMs < entry.expiresAt;
    },

    delete(key) {
      return store.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const { expiresAt } of store.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },

    clear() {
      store.clear();
    },
  };
}

