export function createEventEmitter<EventMap extends Record<string, (...args: unknown[]) => void>>() {
  const events: Record<string, {
    normal: Array<(...args: unknown[]) => void>;
    once: Array<(...args: unknown[]) => void>;
  }> = {};

  function on<K extends keyof EventMap>(event: K, listener: EventMap[K]): number {
    if (!events[event]) {
      events[event] = { normal: [], once: [] };
    }
    events[event].normal.push(listener);
    return listenerCount(event);
  }

  function once<K extends keyof EventMap>(event: K, listener: EventMap[K]): number {
    if (!events[event]) {
      events[event] = { normal: [], once: [] };
    }
    events[event].once.push(listener);
    return listenerCount(event);
  }

  function off<K extends keyof EventMap>(event: K, listener: EventMap[K]): boolean {
    if (!events[event]) {
      return false;
    }

    const { normal, once: onceListeners } = events[event];

    const normalIndex = normal.indexOf(listener);
    if (normalIndex !== -1) {
      normal.splice(normalIndex, 1);
      return true;
    }

    const onceIndex = onceListeners.indexOf(listener);
    if (onceIndex !== -1) {
      onceListeners.splice(onceIndex, 1);
      return true;
    }

    return false;
  }

  function emit<K extends keyof EventMap>(event: K, payload: Parameters<EventMap[K]>): unknown[] {
    if (!events[event]) {
      return [];
    }

    const results: unknown[] = [];
    const { normal, once } = events[event];

    for (const listener of normal) {
      const result = listener(...payload);
      if (result !== undefined) {
        results.push(result);
      }
    }

    for (const listener of once) {
      const result = listener(...payload);
      if (result !== undefined) {
        results.push(result);
      }
    }

    events[event].once = [];

    return results;
  }

  function listenerCount<K extends keyof EventMap>(event: K): number {
    const eventListeners = events[event as string];
    return eventListeners
      ? eventListeners.normal.length + eventListeners.once.length
      : 0;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  } as const;
}
