type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

const createEventEmitter = (): EventEmitter => {
  const events = new Map<string, { lastId: number, listeners: Listener[] }>()

  const getEventState = (event: string) => {
    let eventState = events.get(event)
    if (!eventState) {
      eventState = { lastId: 0, listeners: [] }
      events.set(event, eventState)
    }
    return eventState
  }

  const removeOnceListener = (event: string, listenerToRemove: Listener) => {
    const eventState = events.get(event)
    if (!eventState) return

    const index = eventState.listeners.indexOf(listenerToRemove)
    if (index !== -1) {
      eventState.listeners.splice(index, 1)
      events.set(event, eventState)
    }
  }

  return {
    on(event: string, listener: Listener): number {
      const eventState = getEventState(event)
      eventState.listeners.push(listener)
      return eventState.listeners.length
    },

    once(event: string, listener: Listener): number {
      const eventState = getEventState(event)
      const oneTimeListener: Listener = (payload: unknown) => {
        const result = listener(payload)
        removeOnceListener(event, oneTimeListener)
        return result
      }
      eventState.listeners.push(oneTimeListener)
      return eventState.listeners.length
    },

    off(event: string, listener: Listener): boolean {
      const eventState = events.get(event)
      if (!eventState) return false

      const index = eventState.listeners.indexOf(listener)
      if (index === -1) return false

      eventState.listeners.splice(index, 1)
      events.set(event, eventState)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventState = events.get(event)
      if (!eventState) return []

      return eventState.listeners.map(listener => listener(payload))
    },

    listenerCount(event: string): number {
      const eventState = events.get(event)
      return eventState?.listeners.length ?? 0
    }
  }
}

export { createEventEmitter, EventEmitter, Listener }
