export function createRateLimiter(policy: { windowMs: number, maxRequests: number } = { windowMs: 1000, maxRequests: 3 }) {
    const store = new Map<string, { count: number, resetTime: number }>()

    return {
        allow(key: string, nowMs: number): boolean {
            const item = store.get(key)
            const needsReset = item && nowMs >= item.resetTime

            if (needsReset) {
                store.set(key, { count: 1, resetTime: nowMs + policy.windowMs })
                return true
            }

            const currentCount = item ? item.count : 0
            if (currentCount >= policy.maxRequests) {
                return false
            }

            store.set(key, { count: currentCount + 1, resetTime: item?.resetTime ?? nowMs + policy.windowMs })
            return true
        },

        remaining(key: string, nowMs: number): number {
            const item = store.get(key)
            const needsReset = item && nowMs >= item.resetTime

            if (needsReset) {
                store.set(key, { count: 1, resetTime: nowMs + policy.windowMs })
                return policy.maxRequests - 1
            }

            const currentCount = item?.count ?? 0
            return Math.max(0, policy.maxRequests - currentCount)
        },

        reset(key: string): void {
            store.delete(key)
        }
    }
}
