interface State {
  windowStart: number
  count: number
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

const limit = 3
const windowMs = 1000

const state = new Map<string, State>()

function createRateLimiter(): RateLimiter {
  return {
    allow(key: string, nowMs: number): boolean {
      let current = state.get(key)
      if (!current || nowMs - current.windowStart >= windowMs) {
        state.set(key, { windowStart: nowMs, count: 1 })
        return true
      }
      if (current.count < limit) {
        current.count++
        return true
      }
      return false
    },
    remaining(key: string, nowMs: number): number {
      const current = state.get(key)
      if (!current || nowMs - current.windowStart >= windowMs) {
        return limit
      }
      const remaining = limit - current.count
      return remaining > 0 ? remaining : 0
    },
    reset(key: string): void {
      state.delete(key)
    }
  }
}

export { createRateLimiter, RateLimiter }
