interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let nextId: number = 1
  const todos: Todo[] = []
  const completedIds: Set<number> = new Set()

  function addTodo(text: string): Todo {
    const newTodo: Todo = {
      id: nextId++,
      text,
      completed: false
    }
    todos.push(newTodo)
    return newTodo
  }

  function getTodo(id: number): Todo | undefined {
    return todos.find(todo => todo.id === id)
  }

  function toggleTodo(id: number): void {
    const todo = getTodo(id)
    if (todo !== undefined) {
      todo.completed = !todo.completed
      if (todo.completed) {
        completedIds.add(id)
      } else {
        completedIds.delete(id)
      }
    }
  }

  function deleteTodo(id: number): boolean {
    const index = todos.findIndex(todo => todo.id === id)
    if (index !== -1) {
      const deletedId = todos.splice(index, 1)[0].id
      completedIds.delete(deletedId)
      return true
    }
    return false
  }

  function listTodos(): Todo[] {
    return [...todos]
  }

  function listCompleted(): Todo[] {
    return todos.filter(todo => todo.completed)
  }

  function listPending(): Todo[] {
    return todos.filter(todo => !todo.completed)
  }

  function clearCompleted(): void {
    for (const id of completedIds) {
      const index = todos.findIndex(todo => todo.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
      }
    }
    completedIds.clear()
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  }
}
