export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  type CacheEntry = {
    value: unknown
    expiresAt: number
  }

  const cache = new Map<string, CacheEntry>()

  const set = (key: string, value: unknown, nowMs: number, ttlMs: number | undefined = 1000): void => {
    if (ttlMs === undefined) {
      ttlMs = 1000
    }
    cache.set(key, { value, expiresAt: nowMs + ttlMs })
  }

  const get = (key: string, nowMs: number): unknown => {
    const entry = cache.get(key)
    if (entry !== undefined && nowMs < entry.expiresAt) {
      return entry.value
    }
    return undefined
  }

  const has = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key)
    if (entry === undefined) {
      return false
    }
    return nowMs < entry.expiresAt
  }

  const delete_ = (key: string): boolean => {
    return cache.delete(key)
  }

  const size = (nowMs: number): number => {
    let count = 0
    for (const [key, entry] of cache.entries()) {
      if (nowMs < entry.expiresAt) {
        count++
      }
    }
    return count
  }

  const clear = (): void => {
    cache.clear()
  }

  return {
    set,
    get,
    has,
    delete: delete_,
    size,
    clear
  }
}
