export function createTtlCache(): TtlCache {
  const cache: Record<string, { value: unknown; expiresAt: number }> = {}
  const DEFAULT_TTL = 1000

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      cache[key] = {
        value,
        expiresAt: nowMs + (ttlMs ?? DEFAULT_TTL)
      }
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache[key]
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined
      }
      return entry.value
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache[key]
      return entry !== undefined && nowMs < entry.expiresAt
    },
    delete(key: string): boolean {
      if (key in cache) {
        delete cache[key]
        return true
      }
      return false
    },
    size(nowMs: number): number {
      return Object.values(cache).filter(entry => nowMs < entry.expiresAt).length
    },
    clear(): void {
      Object.keys(cache).forEach(key => delete cache[key])
    }
  }
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
